<?php
session_start(); require_once 'db.php';
if (!isset($_SESSION['usuario_id'])) { header('Location: login.php'); exit; }
$mes=$_GET['mes']??date('Y-m');
if(!preg_match('/^\d{4}-\d{2}$/',$mes)||!DateTime::createFromFormat('!Y-m',$mes)) $mes=date('Y-m');
$primeiro=new DateTime($mes.'-01'); $proximo=(clone $primeiro)->modify('+1 month'); $anterior=(clone $primeiro)->modify('-1 month');
$stmt=$pdo->prepare("SELECT nome_cliente,data,horario_inicio,horario_fim,status FROM agendamentos WHERE data >= :inicio AND data < :fim AND status <> 'Cancelado' ORDER BY data,horario_inicio"); $stmt->execute(['inicio'=>$primeiro->format('Y-m-d'),'fim'=>$proximo->format('Y-m-d')]);
$porDia=[]; foreach($stmt->fetchAll() as $jogo) $porDia[(int)date('j',strtotime($jogo['data']))][]=$jogo;
$diasNoMes=(int)$primeiro->format('t'); $inicioSemana=(int)$primeiro->format('N')-1; $voltar=(($_SESSION['usuario_tipo']??'')==='admin')?'admin.php':'usuario.php';
?>
<!doctype html><html lang="pt-BR"><head><meta charset="utf-8"><meta name="viewport" content="width=device-width,initial-scale=1"><title>Calendário de horários | Red Star</title><link rel="stylesheet" href="style.css"></head><body class="dashboard-page"><header class="topbar"><a class="brand-mini" href="<?=$voltar?>"><img src="assets/logo-red-star.png" alt="Red Star"><span>Red Star<br><small>Point Ball</small></span></a><nav class="nav-tabs"><a href="<?=$voltar?>">← Voltar ao painel</a><a class="active" href="calendario.php">▣ Calendário</a></nav><div class="user-actions"><span>👤 Olá, <?=htmlspecialchars(explode(' ',trim($_SESSION['usuario_nome']))[0],ENT_QUOTES,'UTF-8')?></span><a href="logout.php">↪ Sair</a></div></header><main class="section-wrap calendar-page"><div class="section-heading"><div><div class="panel-kicker">AGENDA RED STAR</div><h1>Calendário de horários</h1><p class="muted">Todos os agendamentos ativos aparecem aqui automaticamente.</p></div></div><div class="calendar-controls"><a class="outline-btn" href="?mes=<?=$anterior->format('Y-m')?>">← Mês anterior</a><h2><?=htmlspecialchars(ucfirst($primeiro->format('F Y')),ENT_QUOTES,'UTF-8')?></h2><a class="outline-btn" href="?mes=<?=$proximo->format('Y-m')?>">Próximo mês →</a></div><div class="calendar-card"><div class="calendar-grid calendar-weekdays"><div>Seg</div><div>Ter</div><div>Qua</div><div>Qui</div><div>Sex</div><div>Sáb</div><div>Dom</div></div><div class="calendar-grid"><?php for($i=0;$i<$inicioSemana;$i++):?><div class="calendar-day muted-day"></div><?php endfor;?><?php for($dia=1;$dia<=$diasNoMes;$dia++):?><div class="calendar-day<?=isset($porDia[$dia])?' has-game':''?>"><strong><?=$dia?></strong><?php foreach($porDia[$dia]??[] as $j):?><article class="game-chip"><b><?=htmlspecialchars($j['nome_cliente'],ENT_QUOTES,'UTF-8')?></b><span><?=date('H:i',strtotime($j['horario_inicio']))?>–<?=date('H:i',strtotime($j['horario_fim']))?></span><small><?=htmlspecialchars($j['status'],ENT_QUOTES,'UTF-8')?></small></article><?php endforeach;?></div><?php endfor;?></div></div></main><footer class="site-footer">© <?=date('Y')?> Red Star Point Ball</footer></body></html>
